[<Interface>]
type Map<'K, 'V> =
    /// <summary>
    /// Removes all elements from the Map.
    /// </summary>
    abstract clear: unit -> unit
    /// <remarks>@returns true if an element in the Map existed and has been removed, or false if the element does not exist.</remarks>
    abstract delete: key: 'K -> bool
    /// <summary>
    /// Executes a provided function once per each key/value pair in the Map, in insertion order.
    /// </summary>
    abstract forEach: callbackfn: Map.ForEach.Callbackfn<'V, 'K> * ?thisArg: obj -> unit
    /// <summary>
    /// Returns a specified element from the Map object. If the value that is associated to the provided key is an object, then you will get a reference to that object and any change made to that object will effectively modify it inside the Map.
    /// </summary>
    /// <remarks>@returns Returns the element associated with the specified key. If no element is associated with the specified key, undefined is returned.</remarks>
    abstract get: key: 'K -> 'V option
    /// <remarks>@returns boolean indicating whether an element with the specified key exists or not.</remarks>
    abstract has: key: 'K -> bool
    /// <summary>
    /// Adds a new element with a specified key and value to the Map. If an element with the same key already exists, the element will be updated.
    /// </summary>
    abstract set: key: 'K * value: 'V -> Map<'K, 'V>
    /// <remarks>@returns the number of elements in the Map.</remarks>
    abstract size: float
    /// <summary>
    /// Returns an iterable of key, value pairs for every entry in the map.
    /// </summary>
    abstract entries: unit -> MapIterator<('K * 'V)>
    /// <summary>
    /// Returns an iterable of keys in the map
    /// </summary>
    abstract keys: unit -> MapIterator<'K>
    /// <summary>
    /// Returns an iterable of values in the map
    /// </summary>
    abstract values: unit -> MapIterator<'V>
    [<ParamObject; Emit("$0")>]
    static member Create (clear: (unit -> unit), delete: ('K -> bool), forEach: Action<Map.ForEach.Callbackfn<'V, 'K>, obj option>, get: ('K -> 'V option), has: ('K -> bool), set: Func<'K, 'V, Map<'K, 'V>>, size: float, entries: (unit -> MapIterator<('K * 'V)>), keys: (unit -> MapIterator<'K>), values: (unit -> MapIterator<'V>)) : Map<'K, 'V> = jsNative

type MapConstructor =
    [<EmitConstructor>]
    abstract Create: unit -> Map<obj, obj>
    [<EmitConstructor>]
    abstract Create<'K, 'V>: ?entries: ('K * 'V)[] -> Map<'K, 'V>
    [<EmitConstructor>]
    abstract Create<'K, 'V>: ?iterable: Iterable<('K * 'V), obj, obj> -> Map<'K, 'V>

[<Interface>]
